271	            tool["name"] = name_ + "." + orig;
272	            names.push_back(tool["name"].get<std::string>());
273	        }
274	
275	        std::lock_guard<std::mutex> lock(tools_mutex_);
276	        cached_tools_json_ = tools.dump();
277	        cached_tool_names_ = std::move(names);
