45	/**
46	 * @brief Sanitize a display_name for use as a log-line bracket label.
47	 *
48	 * Rich-based TUI consumers (and any markdown renderer) interpret
49	 * substrings of the shape `[/foo]` as BBCode close tags and strip
50	 * surrounding markup. A registered server name that started with
51	 * `/` (e.g. by accident or by a path-like identifier) would
52	 * therefore corrupt the consumer's terminal output. We also strip
53	 * `[`, `]`, and control characters that could confuse downstream
54	 * loggers. Falls back to "server" if the input sanitizes to empty.
55	 *
56	 * @param raw Caller-supplied display name (or command for fallback).
57	 * @return Sanitized name safe to embed in `[<name>]` log prefixes.
58	 * @utility
59	 * @version 2.1.5
60	 */
61	static std::string sanitize_display_name(const std::string& raw) {
62	    std::string out;
63	    out.reserve(raw.size());
64	    for (char c : raw) {
65	        if (out.empty() && c == '/') { continue; }
66	        if (c == '[' || c == ']') { continue; }
67	        if (static_cast<unsigned char>(c) < 0x20 || c == 0x7f) { continue; }
68	        out.push_back(c);
69	    }
70	    return out.empty() ? std::string{"server"} : out;
71	}
