130	/**
131	 * @brief Create all three pipe pairs for child communication.
132	 * @param[out] fds Array of 6 fds: stdin_r, stdin_w, stdout_r, stdout_w, stderr_r, stderr_w.
133	 * @return true if all pipes created successfully.
134	 * @utility
135	 * @version 1.8.8
136	 */
137	bool StdioTransport::create_all_pipes(int (&fds)[6]) {
138	    bool ok = create_pipe(fds[0], fds[1]) &&
139	              create_pipe(fds[2], fds[3]) &&
140	              create_pipe(fds[4], fds[5]);
141	    if (!ok) {
142	        logger->error("Failed to create pipes: {}", strerror(errno));
143	        for (auto& fd : fds) { close_fd(fd); }
144	    }
145	    return ok;
146	}
