148	/**
149	 * @brief Spawn child process and open pipes.
150	 * @return true on success.
151	 * @internal
152	 * @version 2.1.5
153	 */
154	bool StdioTransport::open() {
155	    if (connected_) {
156	        return true;
157	    }
158	
159	    if (!open_child_process()) {
160	        return false;
161	    }
162	
163	    connected_ = true;
164	    stderr_thread_ = std::thread(
165	        &StdioTransport::stderr_reader_loop, this);
166	
167	    logger->info("Spawned child process PID {} for '{}' (cmd: {})",
168	                 child_pid_, display_name_, command_);
169	    return true;
170	}
171	
172	/**
173	 * @brief Spawn child process with pipes (open helper).
174	 * @return true on success (stdin_fd_, stdout_fd_, stderr_fd_ set).
175	 * @utility
176	 * @version 1.8.7
177	 */
178	bool StdioTransport::open_child_process() {
179	    int fds[6] = {-1, -1, -1, -1, -1, -1};
180	    if (!create_all_pipes(fds)) {
181	        return false;
182	    }
183	
184	    auto env_strs = build_env();
185	    bool ok = spawn_child(fds[0], fds[3], fds[5], env_strs);
186	
187	    // Close child-side pipe ends in parent
188	    close_fd(fds[0]);
189	    close_fd(fds[3]);
190	    close_fd(fds[5]);
191	
192	    if (!ok) {
193	        close_fd(fds[1]);
194	        close_fd(fds[2]);
195	        close_fd(fds[4]);
196	        return false;
197	    }
198	
199	    stdin_fd_ = fds[1];
200	    stdout_fd_ = fds[2];
201	    stderr_fd_ = fds[4];
202	    return true;
203	}
