258	/**
259	 * @brief Check if child process is alive via kill(pid, 0).
260	 * @return true if connected.
261	 * @internal
262	 * @version 1.8.7
263	 */
264	bool StdioTransport::is_connected() const {
265	    if (!connected_) {
266	        return false;
267	    }
268	    if (child_pid_ > 0 && kill(child_pid_, 0) == 0) {
269	        return true;
270	    }
271	    return false;
272	}
