274	/**
275	 * @brief Cancel any in-flight read by tripping cancel_flag_.
276	 *
277	 * read_line / poll_until_ready short-circuit the next poll tick so
278	 * the pending send_request returns empty within ~50ms (one poll
279	 * slice). Subsequent send_request calls also early-exit until the
280	 * flag is cleared implicitly by a successful open(). (P1-10)
281	 *
282	 * @internal
283	 * @version 2.0.6-rc16
284	 */
285	void StdioTransport::interrupt() {
286	    cancel_flag_.store(true, std::memory_order_release);
287	}
