289	/**
290	 * @brief Build a NULL-terminated argv from command + args.
291	 * @param command Executable.
292	 * @param args Argument list.
293	 * @return char* vector (pointers into command/args; must outlive use).
294	 * @utility
295	 * @version 2.3.7
296	 */
297	static std::vector<char*> build_argv(const std::string& command,
298	                                     const std::vector<std::string>& args) {
299	    std::vector<char*> argv;
300	    argv.push_back(const_cast<char*>(command.c_str()));
301	    for (const auto& arg : args) {
302	        argv.push_back(const_cast<char*>(arg.c_str()));
303	    }
304	    argv.push_back(nullptr);
305	    return argv;
306	}
307	
308	/**
309	 * @brief Build a NULL-terminated envp from env strings.
310	 * @param env_strs "KEY=VALUE" strings.
311	 * @return char* vector (pointers into env_strs; must outlive use).
312	 * @utility
313	 * @version 2.3.7
314	 */
315	static std::vector<char*> build_envp(
316	    const std::vector<std::string>& env_strs) {
317	    std::vector<char*> envp;
318	    for (const auto& e : env_strs) {
319	        envp.push_back(const_cast<char*>(e.c_str()));
320	    }
321	    envp.push_back(nullptr);
322	    return envp;
323	}
