394	/**
395	 * @brief Create pipe pair and set close-on-exec on both ends.
396	 * @param[out] read_fd Read end.
397	 * @param[out] write_fd Write end.
398	 * @return true on success.
399	 * @utility
400	 * @version 1.8.7
401	 */
402	bool StdioTransport::create_pipe(int& read_fd, int& write_fd) {
403	    int fds[2];
404	    if (::pipe(fds) != 0) {
405	        return false;
406	    }
407	    ::fcntl(fds[0], F_SETFD, FD_CLOEXEC);
408	    ::fcntl(fds[1], F_SETFD, FD_CLOEXEC);
409	    read_fd = fds[0];
410	    write_fd = fds[1];
411	    return true;
412	}
