// SPDX-License-Identifier: Apache-2.0
/**
 * @file health_monitor.cpp
 * @brief HealthMonitor implementation.
 * @version 1.8.7
 */

#include <entropic/mcp/health_monitor.h>
#include <entropic/types/logging.h>

static auto logger = entropic::log::get("mcp.health_monitor");

namespace entropic {

/**
 * @brief Construct with reconnection policy.
 * @param policy Backoff policy.
 * @param health_check_interval_ms Ping interval (0 = disabled).
 * @internal
 * @version 1.8.7
 */
HealthMonitor::HealthMonitor(
    ReconnectPolicy policy,
    uint32_t health_check_interval_ms)
    : policy_(std::move(policy)),
      health_check_interval_ms_(health_check_interval_ms) {}

/**
 * @brief Destructor — stops monitor if running.
 * @internal
 * @version 1.8.7
 */
HealthMonitor::~HealthMonitor() {
    stop();
}

/**
 * @brief Start monitoring a server.
 * @param name Server name.
 * @param client Non-owning pointer.
 * @internal
 * @version 1.8.7
 */
void HealthMonitor::watch(
    const std::string& name,
    ExternalMCPClient* client) {

    std::lock_guard<std::mutex> lock(watched_mutex_);
    WatchEntry entry;
    entry.client = client;
    entry.status = client->is_connected() ? "connected" : "disconnected";
    entry.reconnect_attempt = 0;
    entry.next_action = std::chrono::steady_clock::now();
    watched_[name] = entry;

    logger->info("Watching server '{}'", name);
    wake_cv_.notify_one();
}

/**
 * @brief Stop monitoring a server.
 * @param name Server name.
 * @internal
 * @version 1.8.7
 */
void HealthMonitor::unwatch(const std::string& name) {
    std::lock_guard<std::mutex> lock(watched_mutex_);
    watched_.erase(name);
    logger->info("Unwatched server '{}'", name);
}

/**
 * @brief Set callback for status change events.
 * @param cb Callback.
 * @internal
 * @version 1.8.7
 */
void HealthMonitor::set_status_callback(StatusCallback cb) {
    status_callback_ = std::move(cb);
}

/**
 * @brief Start the monitoring thread.
 * @internal
 * @version 1.8.7
 */
void HealthMonitor::start() {
    if (running_) {
        return;
    }
    running_ = true;
    monitor_thread_ = std::thread(
        &HealthMonitor::monitor_loop, this);
    logger->info("Health monitor started");
}

/**
 * @brief Stop monitoring and all reconnection attempts.
 * @internal
 * @version 1.8.7
 */
void HealthMonitor::stop() {
    if (!running_.exchange(false)) {
        return;
    }
    wake_cv_.notify_all();
    if (monitor_thread_.joinable()) {
        monitor_thread_.join();
    }
    logger->info("Health monitor stopped");
}

/**
 * @brief Drain event queue, invoke callbacks on engine thread.
 * @internal
 * @version 1.8.7
 */
void HealthMonitor::process_events() {
    std::vector<HealthEvent> events;
    {
        std::lock_guard<std::mutex> lock(event_mutex_);
        events.swap(event_queue_);
    }

    for (const auto& event : events) {
        if (status_callback_) {
            status_callback_(event);
        }
    }
}

/**
 * @brief Background monitor loop.
 * @callback
 * @version 1.8.7
 */
void HealthMonitor::monitor_loop() {
    constexpr auto poll_interval = std::chrono::milliseconds(500);

    while (running_) {
        {
            std::lock_guard<std::mutex> lock(watched_mutex_);
            auto now = std::chrono::steady_clock::now();
            for (auto& [name, entry] : watched_) {
                if (now >= entry.next_action) {
                    check_server(name, entry);
                }
            }
        }

        std::unique_lock<std::mutex> lock(wake_mutex_);
        wake_cv_.wait_for(lock, poll_interval,
                          [this] { return !running_.load(); });
    }
}

/**
 * @brief Check one server and handle state transitions.
 * @param name Server name.
 * @param entry Watch entry.
 * @utility
 * @version 1.8.7
 */
void HealthMonitor::check_server(
    const std::string& name,
    WatchEntry& entry) {

    bool alive = entry.client->is_connected();

    if (entry.status == "connected" && !alive) {
        // Connection lost — start reconnecting
        auto old = entry.status;
        entry.status = "disconnected";
        entry.reconnect_attempt = 0;
        post_event(name, old, entry.status);
        logger->warn("Server '{}' disconnected", name);
        attempt_reconnect(name, entry);
        return;
    }

    if (entry.status == "disconnected" ||
        entry.status == "reconnecting") {
        attempt_reconnect(name, entry);
        return;
    }

    // Connected + healthy: schedule next check
    if (health_check_interval_ms_ > 0) {
        entry.next_action = std::chrono::steady_clock::now() +
            std::chrono::milliseconds(health_check_interval_ms_);
    } else {
        entry.next_action = std::chrono::steady_clock::now() +
            std::chrono::seconds(5);
    }
}

/**
 * @brief Attempt reconnection for one server.
 * @param name Server name.
 * @param entry Watch entry.
 * @utility
 * @version 2.3.7
 */
void HealthMonitor::attempt_reconnect(
    const std::string& name,
    WatchEntry& entry) {

    if (policy_.exhausted(entry.reconnect_attempt)) {
        if (entry.status != "error") {
            auto old = entry.status;
            entry.status = "error";
            post_event(name, old, "error");
            logger->error("Server '{}' reconnection exhausted "
                          "after {} attempts",
                          name, entry.reconnect_attempt);
        }
        entry.next_action = std::chrono::steady_clock::time_point::max();
        return;
    }

    if (entry.status != "reconnecting") {
        auto old = entry.status;
        entry.status = "reconnecting";
        post_event(name, old, "reconnecting");
    }

    logger->info("Reconnecting to '{}' (attempt {})",
                 name, entry.reconnect_attempt + 1);

    if (entry.client->connect()) {
        on_reconnect_success(name, entry);
        return;
    }

    // Schedule next attempt with backoff
    auto delay = policy_.delay_ms(entry.reconnect_attempt);
    entry.reconnect_attempt++;
    entry.next_action = std::chrono::steady_clock::now() +
                        std::chrono::milliseconds(delay);

    logger->info("Server '{}' reconnect failed, "
                 "retry in {}ms", name, delay);
}

/**
 * @brief Handle a successful reconnect: refresh, mark, enqueue event.
 * @param name Server name.
 * @param entry Watch entry (mutated to connected).
 * @internal
 * @version 2.3.7
 */
void HealthMonitor::on_reconnect_success(const std::string& name,
                                         WatchEntry& entry) {
    auto [added, removed] = entry.client->refresh_tools();
    entry.status = "connected";
    entry.reconnect_attempt = 0;

    HealthEvent evt;
    evt.server_name = name;
    evt.old_status = "reconnecting";
    evt.new_status = "connected";
    evt.added_tools = std::move(added);
    evt.removed_tools = std::move(removed);
    {
        std::lock_guard<std::mutex> lock(event_mutex_);
        event_queue_.push_back(std::move(evt));
    }

    logger->info("Server '{}' reconnected", name);
    entry.next_action = std::chrono::steady_clock::now();
}

/**
 * @brief Post a status change event to the queue.
 * @param name Server name.
 * @param old_status Previous status.
 * @param new_status New status.
 * @utility
 * @version 1.8.7
 */
void HealthMonitor::post_event(
    const std::string& name,
    const std::string& old_status,
    const std::string& new_status) {

    HealthEvent evt;
    evt.server_name = name;
    evt.old_status = old_status;
    evt.new_status = new_status;
    {
        std::lock_guard<std::mutex> lock(event_mutex_);
        event_queue_.push_back(std::move(evt));
    }
}

} // namespace entropic

// SPDX-License-Identifier: Apache-2.0
/**
 * @file health_monitor.h
 * @brief Monitors external MCP server health and triggers reconnection.
 *
 * Runs a background thread that detects connection loss, schedules
 * reconnection with exponential backoff, optionally pings for health,
 * and refreshes tool lists after successful reconnection.
 *
 * Thread model: status changes are posted to a thread-safe event queue.
 * The engine's main thread drains via process_events(). No cross-thread
 * mutation of engine state.
 *
 * @version 1.8.7
 */

#pragma once

#include <entropic/mcp/external_client.h>
#include <entropic/mcp/reconnect_policy.h>

#include <atomic>
#include <chrono>
#include <condition_variable>
#include <functional>
#include <map>
#include <mutex>
#include <string>
#include <thread>
#include <vector>

namespace entropic {

/**
 * @brief Status change event posted by the monitor thread.
 * @version 1.8.7
 */
struct HealthEvent {
    std::string server_name;   ///< Which server changed
    std::string old_status;    ///< Previous status
    std::string new_status;    ///< New status
    std::vector<std::string> added_tools;   ///< Tools added on refresh
    std::vector<std::string> removed_tools; ///< Tools removed on refresh
};

/**
 * @brief Monitors external server connections and handles reconnection.
 *
 * The monitor thread checks connection state periodically and attempts
 * reconnection using ReconnectPolicy. Events are queued for the engine
 * thread to process (no direct cross-thread mutation).
 *
 * @version 1.8.7
 */
class HealthMonitor {
public:
    /**
     * @brief Callback invoked on engine thread when processing events.
     * @version 1.8.7
     */
    using StatusCallback = std::function<void(const HealthEvent&)>;

    /**
     * @brief Construct with reconnection policy.
     * @param policy Backoff policy for reconnection attempts.
     * @param health_check_interval_ms Ping interval (0 = disabled).
     * @version 1.8.7
     */
    HealthMonitor(ReconnectPolicy policy,
                  uint32_t health_check_interval_ms = 0);

    ~HealthMonitor();

    /**
     * @brief Start monitoring a server.
     * @param name Server name.
     * @param client Non-owning pointer to ExternalMCPClient.
     * @version 1.8.7
     */
    void watch(const std::string& name, ExternalMCPClient* client);

    /**
     * @brief Stop monitoring a server.
     * @param name Server name.
     * @version 1.8.7
     */
    void unwatch(const std::string& name);

    /**
     * @brief Set callback for status change events.
     * @param cb Callback invoked by process_events().
     * @version 1.8.7
     */
    void set_status_callback(StatusCallback cb);

    /**
     * @brief Start the monitoring thread.
     * @version 1.8.7
     */
    void start();

    /**
     * @brief Stop monitoring and all reconnection attempts.
     * @version 1.8.7
     */
    void stop();

    /**
     * @brief Drain event queue, invoke callbacks (call on engine thread).
     * @version 1.8.7
     */
    void process_events();

private:
    ReconnectPolicy policy_;                     ///< Backoff policy
    uint32_t health_check_interval_ms_;          ///< Ping interval
    StatusCallback status_callback_;             ///< Engine-thread callback

    /**
     * @brief Per-server monitoring state.
     * @version 1.8.7
     */
    struct WatchEntry {
        ExternalMCPClient* client;               ///< Non-owning
        std::string status;                      ///< Current status
        uint32_t reconnect_attempt;              ///< Attempt counter
        std::chrono::steady_clock::time_point next_action; ///< Next check/reconnect time
    };

    std::map<std::string, WatchEntry> watched_;  ///< Monitored servers
    std::mutex watched_mutex_;                   ///< Guards watched_

    std::vector<HealthEvent> event_queue_;        ///< Pending events
    std::mutex event_mutex_;                     ///< Guards event_queue_

    std::thread monitor_thread_;                 ///< Background thread
    std::atomic<bool> running_{false};           ///< Thread control
    std::condition_variable wake_cv_;            ///< Wake for immediate check
    std::mutex wake_mutex_;                      ///< Guards wake_cv_

    /**
     * @brief Monitor loop (background thread).
     * @callback
     * @version 1.8.7
     */
    void monitor_loop();

    /**
     * @brief Check one server and handle state transitions.
     * @param name Server name.
     * @param entry Watch entry (mutated).
     * @utility
     * @version 1.8.7
     */
    void check_server(const std::string& name, WatchEntry& entry);

    /**
     * @brief Attempt reconnection for a single server.
     * @param name Server name.
     * @param entry Watch entry (mutated on success/failure).
     * @utility
     * @version 1.8.7
     */
    void attempt_reconnect(const std::string& name,
                           WatchEntry& entry);

    /**
     * @brief Handle a successful reconnect: refresh tools, mark
     *        connected, enqueue the event.
     *
     * Extracted from attempt_reconnect to keep it knots-clean.
     *
     * @param name Server name.
     * @param entry Watch entry (mutated to connected).
     * @internal
     * @version 2.3.7
     */
    void on_reconnect_success(const std::string& name,
                              WatchEntry& entry);

    /**
     * @brief Post a status change event to the queue.
     * @param name Server name.
     * @param old_status Previous status.
     * @param new_status New status.
     * @utility
     * @version 1.8.7
     */
    void post_event(const std::string& name,
                    const std::string& old_status,
                    const std::string& new_status);
};

} // namespace entropic

